import Foundation

@MainActor
extension SharedMediaNativeOriginalOwner {
    /// IDs are caller-owned and fixed before acquiring locks. No fresh identity
    /// is generated by admission or acknowledgement recovery.
    func appReceivingRequest(packageID: UUID, pairIDs: [UUID], operationID: UUID, queueID: UUID,
                             observationID: UUID, bindingID: UUID, generation: UUID, eventID: UUID,
                             timestamp: Date) async throws -> SharedMediaNativeAppReceivingRequest {
        try await withReceivingLocks(queueID: queueID.uuidString, observationID: observationID.uuidString) { lock in
            try await self.appReceivingWorkflow(lock: lock) {
                try await $0.request(packageID: packageID, pairIDs: pairIDs, operationID: operationID, queueID: queueID,
                    observationID: observationID, bindingID: bindingID, generation: generation, eventID: eventID, timestamp: timestamp)
            }
        }
    }
    func receiveAppPhotos(_ request: SharedMediaNativeAppReceivingRequest) async throws -> SharedMediaNativeConsumerCohort {
        try await withReceivingLocks(queueID: request.cohort.originQueueID, observationID: request.cohort.observationID) { lock in
            try await self.appReceivingWorkflow(lock: lock) { try await $0.apply(request) }
        }
    }
    /// Discovery precedes fresh ID generation. A saved slot is immutable even
    /// when its source files are currently unavailable.
    func stageAppReceiving(packageID: UUID, draftGeneration: UUID, pairIDs: [UUID]) async throws -> SharedMediaNativeReceivingIntent.Prepared {
        let saved = try await discoverAppReceivingIntent(packageID: packageID)
        let identity = try SharedMediaNativeReceivingStageIdentity(saved: saved)
        return try await withReceivingLocks(queueID: identity.queueID.uuidString, observationID: identity.observationID.uuidString) { lock in
            try await self.appReceivingWorkflow(lock: lock) {
                try await $0.stage(packageID: packageID, draftGeneration: draftGeneration, pairIDs: pairIDs, identity: identity)
            }
        }
    }
    func receiveAppPrepared(_ prepared: SharedMediaNativeReceivingIntent.Prepared) async throws -> SharedMediaNativeConsumerCohort {
        try await withReceivingLocks(queueID: prepared.queueID.uuidString, observationID: prepared.observationID.uuidString) { lock in
            try await self.appReceivingWorkflow(lock: lock) { try await $0.receivePrepared(prepared) }
        }
    }
    func abandonAppReceiving(_ prepared: SharedMediaNativeReceivingIntent.Prepared) async throws -> SharedMediaNativeReceivingIntent.Abandoned {
        try await withReceivingLocks(queueID: prepared.queueID.uuidString, observationID: prepared.observationID.uuidString) { lock in
            try await self.appReceivingWorkflow(lock: lock) { try $0.abandonPrepared(prepared) }
        }
    }
    func appReleaseStageRequest(_ prepared: SharedMediaNativeReceivingIntent.Prepared,
                                releaseID: UUID) async throws -> SharedMediaNativeReleaseStageAdmission {
        try await withReceivingLocks(queueID: prepared.queueID.uuidString, observationID: prepared.observationID.uuidString) { lock in
            try await self.appReleaseStageWorkflow(lock: lock) { operation in
                let request = try operation.request(packageID: prepared.package.id, releaseID: releaseID)
                guard request.request.preparedSHA256 == SharedMediaAcquisitionEncoding.digest(try prepared.encoded()) else {
                    throw SharedMediaStorageFailure.stale
                }
                return request
            }
        }
    }
    func stageAppRelease(_ admission: SharedMediaNativeReleaseStageAdmission) async throws -> SharedMediaNativeAppReleaseStageOperations.Saved {
        let request = admission.request
        return try await withReceivingLocks(queueID: request.queueID.uuidString, observationID: request.observationID.uuidString) { lock in
            try await self.appReleaseStageWorkflow(lock: lock) { try await $0.apply(admission) }
        }
    }
    func recoverAppRelease(_ request: SharedMediaNativeReleaseStartRequest) async throws -> SharedMediaNativeAppReleaseStageOperations.Saved {
        try await withReceivingLocks(queueID: request.queueID.uuidString, observationID: request.observationID.uuidString) { lock in
            try await self.appReleaseStageWorkflow(lock: lock) { try $0.reconcile(request) }
        }
    }
    func startAppRelease(_ request: SharedMediaNativeReleaseStartRequest) async throws -> SharedMediaNativeReceivingReleaseValues.Progress {
        try await withReceivingLocks(queueID: request.queueID.uuidString, observationID: request.observationID.uuidString) { lock in
            try await self.appReleaseStageWorkflow(lock: lock) { try await $0.start(request) }
        }
    }
    func recoverAppReleaseStart(_ progress: SharedMediaNativeReceivingReleaseValues.Progress) async throws -> SharedMediaNativeReceivingReleaseValues.Progress {
        let plan = progress.plan
        return try await withReceivingLocks(queueID: plan.queueID.uuidString, observationID: plan.observationID.uuidString) { lock in
            try await self.appReleaseStageWorkflow(lock: lock) { try $0.reconcileStart(progress) }
        }
    }
    #if DEBUG
    func frozenAppReleasePairForTesting(_ progress: SharedMediaNativeReceivingReleaseValues.Progress) async throws -> SharedMediaNativeReleasePairAttempt? {
        let plan = progress.plan
        return try await withReceivingLocks(queueID: plan.queueID.uuidString, observationID: plan.observationID.uuidString) { lock in
            try await self.appReleaseStageWorkflow(lock: lock) { try $0.frozenPairForTesting(progress) }
        }
    }
    #endif
    func retireAppReleasePair(_ progress: SharedMediaNativeReceivingReleaseValues.Progress) async throws -> SharedMediaNativeReceivingReleaseValues.Progress {
        let plan = progress.plan
        return try await withReceivingLocks(queueID: plan.queueID.uuidString, observationID: plan.observationID.uuidString) { lock in
            try await self.appReleaseStageWorkflow(lock: lock) { try await $0.retirePair(progress) }
        }
    }
    func removeAppReleasePair(_ progress: SharedMediaNativeReceivingReleaseValues.Progress) async throws -> SharedMediaNativeReceivingReleaseValues.Progress {
        let plan = progress.plan
        return try await withReceivingLocks(queueID: plan.queueID.uuidString, observationID: plan.observationID.uuidString) { lock in
            try await self.appReleaseStageWorkflow(lock: lock) { try await $0.removePair(progress) }
        }
    }
    func recoverAppReleasePair(_ progress: SharedMediaNativeReceivingReleaseValues.Progress) async throws -> SharedMediaNativeReceivingReleaseValues.Progress {
        let plan = progress.plan
        return try await withReceivingLocks(queueID: plan.queueID.uuidString, observationID: plan.observationID.uuidString) { lock in
            try await self.appReleaseStageWorkflow(lock: lock) { try $0.reconcilePair(progress) }
        }
    }
    /// Uses retained IDs only, and returns typed saved evidence without inventing
    /// the consumed stage header. The supplied Prepared is descriptive, not authority.
    func discoverAppRelease(_ prepared: SharedMediaNativeReceivingIntent.Prepared) async throws -> SharedMediaNativeAppReleaseStageOperations.Saved? {
        try await withReceivingLocks(queueID: prepared.queueID.uuidString, observationID: prepared.observationID.uuidString) { lock in
            try await self.appReleaseStageWorkflow(lock: lock) { try $0.discover(prepared: prepared) }
        }
    }
    private func withReceivingLocks<T: Sendable>(queueID: String, observationID: String,
                                                 body: @MainActor (SharedMediaNativeReceivingLockGrant) async throws -> T) async throws -> T {
        let coordinator = ScanInferencePersistenceCoordinator.shared
        let held = await coordinator.acquireAll(scanIds: [queueID, observationID])
        let lock = SharedMediaNativeReceivingLockGrant()
        do {
            try Task.checkCancellation()
            // appReceivingWorkflow immediately checks the current account/owner
            // and acquires its work lease before any repository read or mutation.
            let value = try await body(lock)
            lock.close()
            await coordinator.releaseAll(scanIds: held)
            return value
        } catch {
            lock.close()
            await coordinator.releaseAll(scanIds: held)
            throw error
        }
    }
}

/// Minted only after both canonical coordinator locks are held; never survives
/// lock release and never escapes the lock-owning wrapper's private closure.
@MainActor
final class SharedMediaNativeReceivingLockGrant {
    private var active = true
    fileprivate init() {}
    fileprivate func close() { active = false }
    func validate() throws {
        try Task.checkCancellation()
        guard active else { throw SharedMediaStorageFailure.closed }
    }
}

/// Only the lock-owning native owner generates fresh submission identities.
/// Existing discovery supplies the exact immutable IDs instead of new ones.
struct SharedMediaNativeReceivingStageIdentity: Sendable {
    let operationID: UUID, queueID: UUID, observationID: UUID, bindingID: UUID, generation: UUID, eventID: UUID
    let timestamp: Date
    let savedBytes: Data?
    fileprivate init(saved: SharedMediaNativeReceivingIntent.Prepared?) throws {
        if let saved {
            operationID = saved.operationID; queueID = saved.queueID; observationID = saved.observationID
            bindingID = saved.bindingID; generation = saved.generation; eventID = saved.eventID
            timestamp = Date(timeIntervalSinceReferenceDate: Double(bitPattern: saved.timestampBits))
            savedBytes = try saved.encoded()
        } else {
            operationID = UUID(); queueID = UUID(); observationID = UUID(); bindingID = UUID()
            generation = UUID(); eventID = UUID(); timestamp = Date(); savedBytes = nil
        }
    }
}

/// Descriptive identity selection occurs before its coordinator locks; the
/// complete observed slot must still match under those locks before any save.
struct SharedMediaNativeReceivingRestageIdentity: Sendable {
    let observed: SharedMediaNativeReceivingIntentGraph.Row
    let predecessor: SharedMediaNativeReceivingIntent.Abandoned
    let identity: SharedMediaNativeReceivingStageIdentity
    let savedSuccessor: SharedMediaNativeReceivingIntent.Prepared?
    fileprivate init(observed: SharedMediaNativeReceivingIntentGraph.Row,
                     predecessor: SharedMediaNativeReceivingIntent.Abandoned) throws {
        self.observed = observed; self.predecessor = predecessor
        let slot = try SharedMediaNativeReceivingSlot.decode(observed, profile: predecessor.profile)
        switch slot {
        case .abandoned(let saved):
            guard try saved.encoded() == predecessor.encoded() else { throw SharedMediaStorageFailure.stale }
            identity = try .init(saved: nil); savedSuccessor = nil
        case .prepared(let prepared):
            guard prepared.version == 2, prepared.package.id == predecessor.package.id,
                  prepared.intentRevision == (try SharedMediaStoragePolicy.add(predecessor.revision, 1)),
                  prepared.restagedFromSHA256 == (try SharedMediaAcquisitionEncoding.digest(predecessor.encoded())) else {
                throw SharedMediaStorageFailure.stale
            }
            identity = try .init(saved: prepared); savedSuccessor = prepared
        case .received: throw SharedMediaStorageFailure.closed
        }
        guard Set([identity.operationID, identity.queueID, identity.observationID, identity.bindingID, identity.generation, identity.eventID])
            .isDisjoint(with: [predecessor.operationID, predecessor.queueID, predecessor.observationID, predecessor.bindingID,
                              predecessor.generation, predecessor.eventID]) else { throw SharedMediaStorageFailure.conflict }
    }
}

@MainActor
extension SharedMediaNativeOriginalOwner {
    func restageAppReceiving(_ predecessor: SharedMediaNativeReceivingIntent.Abandoned,
                             draftGeneration: UUID, pairIDs: [UUID]) async throws -> SharedMediaNativeReceivingIntent.Prepared {
        guard let row = try await discoverAppReceivingSlot(packageID: predecessor.package.id) else {
            throw SharedMediaStorageFailure.stale
        }
        let identity = try SharedMediaNativeReceivingRestageIdentity(observed: row, predecessor: predecessor)
        return try await withReceivingLocks(queueID: identity.identity.queueID.uuidString,
                                            observationID: identity.identity.observationID.uuidString) { lock in
            try await self.appReceivingWorkflow(lock: lock) {
                try await $0.restage(identity, draftGeneration: draftGeneration, pairIDs: pairIDs)
            }
        }
    }
}
